export const LOOK_GROUPS = ['Alive', 'Signature', 'Photo', 'Accent', 'Surface', 'Depth', 'Shape', 'Line', 'Type', 'Pattern', 'Vibe', 'Reset'];
// Uniform corner-radius patch so the editor's own radius controls stay in sync.
const corners = (n) => ({ borderRadiusTL: n, borderRadiusTR: n, borderRadiusBR: n, borderRadiusBL: n });
const on = (state, styles) => Object.fromEntries(Object.entries(styles).map(([property, value]) => [`__froamState:${state}:${property}`, value]));
const EASE = 'cubic-bezier(0.2, 0.8, 0.2, 1)';
const SPRING = 'cubic-bezier(0.34, 1.56, 0.64, 1)';
const mix = (color, percent, other = 'transparent') => `color-mix(in srgb, ${color} ${percent}%, ${other})`;
/* A look written for words: the same recipe on a heading as on a link. */
const words = (recipe) => ({ styles: recipe, text: recipe });
const PHOTO = 'linear-gradient(160deg, #7dd3fc, #fbbf24 60%, #f472b6)';
/** A hex colour's hue in degrees, to tint a photo in the brand colour. */
function hueOf(hex) {
    const digits = hex.trim().replace(/^#/, '');
    const full = digits.length === 3 ? digits.split('').map((digit) => digit + digit).join('') : digits;
    if (!/^[0-9a-f]{6}$/i.test(full))
        return 230;
    const [r, g, b] = [0, 2, 4].map((index) => parseInt(full.slice(index, index + 2), 16) / 255);
    const max = Math.max(r, g, b);
    const min = Math.min(r, g, b);
    const range = max - min;
    if (!range)
        return 230;
    const h = max === r ? (g - b) / range + (g < b ? 6 : 0) : max === g ? (b - r) / range + 2 : (r - g) / range + 4;
    return Math.round(h * 60);
}
